/* ==========================================================================
   Embedded subset of Noto Sans (SIL Open Font License) + company logo.
   jsPDF's built-in helvetica font cannot encode the Indian Rupee symbol (U+20B9);
   passing a currency string containing it caused jsPDF to mangle the whole string
   (null bytes between every digit, rupee became a stray glyph). These subsets contain
   only the ASCII + rupee glyphs needed by the quotation PDF, so they stay small and
   work fully offline. Weights: regular + bold.
   Source: https://github.com/google/fonts (OFL-1.1)

   The logo (business assets/logo.png, 512x272 RGBA) is also embedded here so the PDF
   generation stays self-contained and works when opened directly from disk.
   ========================================================================== */
(function () {
  window.TQG_FONTS = {
    regular: "",
    bold: "",
    logo: ""
  };
})();
